noncomputable def VTask.memPartition {α : Type u_1} (f : ℕ → Set α) (n : ℕ) : Set (Set α) :=
match n with
| 0 => {univ}
| succ n' =>
  let prev_partition := VTask.memPartition f n';
  let rec refine_partition (p : Set α) (acc : List (Set α)) : List (Set α) :=
    match p with
    | ∅ => acc
    | s =>
      let s_f_n := s ∩ f n';
      let s_not_f_n := s \ f n';
      refine_partition s_f_n (refine_partition s_not_f_n (acc ++ [s_f_n] ++ [s_not_f_n]))
  prev_partition.bind(refine_partition)
